// New requirements:
// - Fix the completion toggle.
// - Don't directly mutate state.
// - Add a delete button.
// - Completed tasks should have line-through styling.
// - Preserve existing tasks and functionality.


// ===========================================
//          Code After Solved Bugs
// ===========================================
import { useState } from "react";
function Task7() {
  const [todos, setTodos] = useState([
    { id: 1, name: "Learn JavaScript", completed: false },
    { id: 2, name: "Learn React", completed: false }
  ]);
  const completedStyle={
    textDecoration:"line-through",
    color:"gray"
  }

//  ============================
//     Added Toggle Logic
// ============================

  function toggleTodo(id) {
    const updatedTodos = todos.map((todo) => {
      if (todo.id === id) {
        todo.completed = !todo.completed;
      }
      return todo;
    });

    setTodos(updatedTodos);
  }

//  ============================
//     Added Delete Logic
// ============================
  
  function handleDelete(id){
    const filterDeletedTodos=todos.filter((todo)=>{
        return todo.id!==id;
    })
    setTodos(filterDeletedTodos)
  }

//  ============================
//     Display all todos Logic
// ============================


  return (
    <div>
      {todos.map((todo) => (
        <div key={todo.id}>
          <span style={todo.completed===true?completedStyle:{}}>{todo.name}</span>
          <button onClick={() => toggleTodo(todo.id)}>
            Toggle
          </button>
          <p>{todo.completed ? "Completed" : "Pending"}</p>
          <button onClick={()=>{handleDelete(todo.id)}}>Delete</button>
        </div>
      ))}
    </div>
  );
}

export default Task7;